package com.android.tools.lint.checks;

import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.JavaContext;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.SourceCodeScanner;
import com.intellij.psi.PsiClassType;
import com.intellij.psi.PsiModifier;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.uast.UAnnotation;
import org.jetbrains.uast.UClass;
import org.jetbrains.uast.UField;

import java.util.Collections;
import java.util.List;

public class ParcelDetector extends Detector implements SourceCodeScanner {

    private static final String PARCELABLE = "android.os.Parcelable";
    private static final String CREATOR_TYPE = "android.os.Parcelable.Creator";
    private static final String PARCELIZE_OLD = "kotlinx.android.parcel.Parcelize";
    private static final String PARCELIZE_NEW = "kotlinx.parcelize.Parcelize";

    @Override
    public List<String> applicableSuperClasses() {
        return Collections.singletonList(PARCELABLE);
    }

    @Override
    public void visitClass(@NotNull JavaContext context, @NotNull UClass declaration) {
        if (declaration.isInterface() || declaration.isEnum()
                || declaration.hasModifierProperty(PsiModifier.ABSTRACT)) {
            return;
        }

        if (hasParcelizeAnnotation(declaration)) {
            return;
        }

        UField creatorField = findCreatorField(declaration);
        if (creatorField == null) {
            String message = "This class implements Parcelable but does not provide a CREATOR field";
            // Add quickfix for @Parcelize if Kotlin data class?
            context.report(ISSUE, declaration, context.getNameLocation(declaration), message);
            return;
        }

        // Check @JvmField for Kotlin
        if (context.getFile().getName().endsWith(".kt")) {
            if (!hasJvmFieldAnnotation(creatorField)) {
                context.report(
                    ISSUE,
                    creatorField,
                    context.getNameLocation(creatorField),
                    "Field should be annotated with @JvmField"
                );
            }
        }
    }

    private static UField findCreatorField(@NotNull UClass cls) {
        for (UField field : cls.getFields()) {
            if ("CREATOR".equals(field.getName())
                    && field.hasModifierProperty(PsiModifier.STATIC)) {
                if (field.getType() instanceof PsiClassType) {
                    PsiClassType classType = (PsiClassType) field.getType();
                    if (classType.resolve() != null
                            && CREATOR_TYPE.equals(classType.resolve().getQualifiedName())) {
                        return field;
                    }
                }
            }
        }
        return null;
    }

    private static boolean hasParcelizeAnnotation(@NotNull UClass cls) {
        for (UAnnotation annotation : cls.getAnnotations()) {
            String name = annotation.getQualifiedName();
            if (PARCELIZE_OLD.equals(name) || PARCELIZE_NEW.equals(name)) {
                return true;
            }
        }
        return false;
    }

    private static boolean hasJvmFieldAnnotation(@NotNull UField field) {
        for (UAnnotation annotation : field.getAnnotations()) {
            if ("kotlin.jvm.JvmField".equals(annotation.getQualifiedName())) {
                return true;
            }
        }
        return false;
    }

    public static final Issue ISSUE = Issue.create(
            "ParcelCreator",
            "Missing Parcelable CREATOR field",
            "According to the Parcelable documentation, classes implementing Parcelable must "
                    + "declare a static field named CREATOR of type android.os.Parcelable.Creator.",
            Category.CORRECTNESS,
            9,
            Severity.ERROR,
            new Implementation(ParcelDetector.class, Scope.JAVA_FILE_SCOPE)
    );
}
```

