private static UField findCreatorFieldInClassOnly(@NotNull UClass cls, boolean requireStatic) {
    for (UField field : cls.getFields()) {
        if (!"CREATOR".equals(field.getName())) continue;
        if (requireStatic && !field.hasModifierProperty(PsiModifier.STATIC)) continue;
