Let's design corrected detector:

```
public class ParcelDetector extends Detector implements SourceCodeScanner {
    private static final String PARCELABLE = "android.os.Parcelable";
    private static final String CREATOR_TYPE = "android.os.Parcelable.Creator";
    private static final String PARCELIZE_OLD = "kotlinx.android.parcel.Parcelize";
    private static final String PARCELIZE_NEW = "kotlinx.parcelize.Parcelize";
    private static final String JVM_FIELD = "kotlin.jvm.JvmField";

    @Override public List<String> applicableSuperClasses() { return Collections.singletonList(PARCELABLE); }

    @Override public void visitClass(@NotNull JavaContext context, @NotNull UClass declaration) {
        if (declaration.isInterface() || declaration.isEnum() || declaration.isAnnotationType() || declaration.hasModifierProperty(PsiModifier.ABSTRACT)) return;
        if (isParcelizeAnnotated(declaration)) return;

        CreatorField creator = findCreator(declaration);
        if (creator == null) {
            reportMissingCreator(context, declaration);
            return;
        }

        if (creator.isStatic) {
            return;
        }

        // Kotlin non-static property: needs @JvmField to generate static field
        if (isKotlin(context)) {
            if (!isJvmFieldAnnotated(creator.field)) {
                reportJvmField(context, creator.field);
            }
        } else {
            reportMissingCreator(context, declaration);
        }
    }
}
```

